export class GlueBudget {
  public readonly leadingNatural: number;
  public readonly leadingConsumed: number;
  public readonly trailingNatural: number;
  public readonly trailingConsumed: number;

  constructor(leadingNatural: number, leadingConsumed: number, trailingNatural: number, trailingConsumed: number) {
    this.leadingNatural = leadingNatural;
    this.leadingConsumed = leadingConsumed;
    this.trailingNatural = trailingNatural;
    this.trailingConsumed = trailingConsumed;
  }

  public get leadingRemaining(): number {
    return this.get_leadingRemaining();
  }
   get_leadingRemaining(): number {
    return Math.max(0, this.leadingNatural - this.leadingConsumed);
  }

  public get trailingRemaining(): number {
    return this.get_trailingRemaining();
  }
   get_trailingRemaining(): number {
    return Math.max(0, this.trailingNatural - this.trailingConsumed);
  }

  public toString(): string {
    return `GlueBudget(leadingNatural=${this.leadingNatural}, leadingConsumed=${this.leadingConsumed}, trailingNatural=${this.trailingNatural}, trailingConsumed=${this.trailingConsumed})`;
  }
}

